func buildSort(idx int, sm map[string]interface{}) (Stage, error) {
        keysRaw, ok := sm["keys"]
        if !ok {
                return nil, fmt.Errorf("config: stage %d: sort.keys is required", idx)
        }
        list, ok := keysRaw.([]interface{})
        if !ok {
                return nil, fmt.Errorf("config: stage %d: sort.keys must be a list", idx)
        }

        keys := make([]SortKey, 0, len(list))
        for j, item := range list {
                km, ok := item.(map[string]interface{})
                if !ok {
                        return nil, fmt.Errorf("config: stage %d: sort key %d must be a mapping", idx, j+1)
                }

                column, ok := getString(km, "column")
                if !ok || column == "" {
                        return nil, fmt.Errorf("config: stage %d: sort key %d column is required", idx, j+1)
                }

                order, ok := getString(km, "order")
                if !ok || order == "" {
                        order = "asc"
                }
                if order != "asc" && order != "desc" {
                        return nil, fmt.Errorf("config: stage %d: sort key %d order must be asc or desc", idx, j+1)
                }

                as, ok := getString(km, "as")
                if !ok || as == "" {
                        as = "string"
                }
                if as != "string" && as != "number" {
                        return nil, fmt.Errorf("config: stage %d: sort key %d as must be string or number", idx, j+1)
                }

                keys = append(keys, SortKey{Column: column, Order: order, As: as})
        }

        return &SortStage{keys: keys}, nil
}

