	column string
	into   string
}

type windowConfig struct {
	timeColumn       string
	timeFormat       string
	emitTimeFormat   string
	windowType       string
	tumbleSize       float64
	tumbleOrigin     float64
	slideSize        float64
	slideStep        float64
	slideOrigin      float64
	sessionGap       float64
	sessionMaxDur    float64
	sessionHasMax    bool
	partitionBy      []string
	aggregates       []windowAggConfig
	windowStartInto  string
	windowEndInto    string
	emitEmptyWindows bool
	onLate           string
	onMissingTime    string
	onNonParseable   string
	emitSchema       string
	metricNameInto   string
	metricValueInto  string
	emitMode         string
	outOrder         string
}

type WindowStage struct {
	cfg windowConfig
}

func (s *WindowStage) Apply(in []*record.Record, stderr io.Writer, strict bool, stats *Stats) ([]*record.Record, error) {
	type winKey struct {
		start      float64
		end        float64
		partition  string
		partVals   []string
	}
	type aggState struct {
		count   int
		sum     float64
		numVals []float64
		strVals []string
		distinct map[string]struct{}
		first   string
		last    string
		hasFirst bool
	}
	states := map[winKey]*aggState{}
	var keyOrder []winKey

	watermark := math.Inf(-1)
	maxSeen := math.Inf(-1)

	ensureState := func(k winKey) *aggState {
		if st, ok := states[k]; ok {
			return st
		}
		st := &aggState{distinct: map[string]struct{}{}}
		states[k] = st
		keyOrder = append(keyOrder, k)
		return st
	}

	for rowIdx, r := range in {
		rNum := rowIdx + 1
		tvStr, hasTime := r.Get(s.cfg.timeColumn)
		if !hasTime || tvStr == "" {
			switch s.cfg.onMissingTime {
			case "drop":
				stats.DroppedMissing++
				fmt.Fprintf(stderr, "flowctl: window: drop missing-time row %d\n", rNum)
				if strict {
					return nil, fmt.Errorf("strict: missing column %s", s.cfg.timeColumn)
				}
				continue
			case "error":
				return nil, fmt.Errorf("flowctl: window: missing column %s at row %d", s.cfg.timeColumn, rNum)
			default:
				return nil, fmt.Errorf("flowctl: window: missing column %s at row %d", s.cfg.timeColumn, rNum)
			}
		}

		tv, err := s.parseTime(tvStr)
		if err != nil {
			switch s.cfg.onNonParseable {
			case "drop":
				stats.DroppedNonNumeric++
				fmt.Fprintf(stderr, "flowctl: window: drop non-parseable-time row %d\n", rNum)
				if strict {
					return nil, fmt.Errorf("strict: non-parseable-time row %d", rNum)
				}
				continue
			case "error":
				return nil, fmt.Errorf("flowctl: window: non-parseable time value in column %s at row %d", s.cfg.timeColumn, rNum)
			default:
				return nil, fmt.Errorf("flowctl: window: non-parseable time value in column %s at row %d", s.cfg.timeColumn, rNum)
			}
		}

		if tv < maxSeen-s.cfg.allowedLateness() {
			switch s.cfg.onLate {
			case "drop":
				stats.DroppedLate++
				fmt.Fprintf(stderr, "flowctl: window: drop late row %d\n", rNum)
				if strict {
					return nil, fmt.Errorf("strict: late row %d", rNum)
				}
				continue
			case "include":
				// fall through and fold late record
			case "error":
				return nil, fmt.Errorf("flowctl: window: late row %d beyond allowed_lateness", rNum)
			default:
				return nil, fmt.Errorf("flowctl: window: late row %d beyond allowed_lateness", rNum)
			}
		} else {
			if tv > maxSeen {
				maxSeen = tv
				watermark = maxSeen
			}
		}

		partVals := make([]string, len(s.cfg.partitionBy))
		for i, col := range s.cfg.partitionBy {
			v, _ := r.Get(col)
			partVals[i] = v
		}
		partKey := strings.Join(partVals, "\x00")

		windows := s.windowsFor(tv)
		for _, w := range windows {
			if s.cfg.onLate == "include" && tv < maxSeen-s.cfg.allowedLateness() && s.cfg.windowType == "session" {
				w.start = tv
				w.end = tv
			}
			k := winKey{start: w.start, end: w.end, partition: partKey, partVals: partVals}
			st := ensureState(k)
			st.count++
			for _, agg := range s.cfg.aggregates {
				s.applyAggregate(st, agg, r, rNum)
			}
		}
	}

	// Session windows are already data-driven; no extra closing needed because windowsFor closed them.
	keys := make([]winKey, 0, len(states))
	for k := range states {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].start != keys[j].start {
			return keys[i].start < keys[j].start
		}
		if keys[i].end != keys[j].end {
			return keys[i].end < keys[j].end
		}
		return keys[i].partition < keys[j].partition
	})

	out := make([]*record.Record, 0, len(keys)*len(s.cfg.aggregateOutputs()))
	for _, k := range keys {
		st := states[k]
		vals := s.renderAggregates(st)
		if s.cfg.emitSchema == "long" {
			for i, agg := range s.cfg.aggregates {
				nr := record.New()
				for j, col := range s.cfg.partitionBy {
					nr.Set(col, k.partVals[j])
				}
				nr.Set(s.cfg.windowStartInto, s.renderTime(k.start))
				nr.Set(s.cfg.windowEndInto, s.renderTime(k.end))
				nr.Set(s.cfg.metricNameInto, agg.into)
				nr.Set(s.cfg.metricValueInto, vals[i])
				out = append(out, nr)
			}
		} else {
			nr := record.New()
			for j, col := range s.cfg.partitionBy {
				nr.Set(col, k.partVals[j])
			}
			nr.Set(s.cfg.windowStartInto, s.renderTime(k.start))
			nr.Set(s.cfg.windowEndInto, s.renderTime(k.end))
			for i, agg := range s.cfg.aggregates {
				nr.Set(agg.into, vals[i])
			}
			out = append(out, nr)
		}
		}
	}

	return out, nil
}

type windowRange struct {
	start float64
	end   float64
}

func (s *WindowStage) parseTime(v string) (float64, error) {
	switch s.cfg.timeFormat {
	case "unix_seconds":
		f, err := strconv.ParseFloat(v, 64)
		if err != nil || math.IsNaN(f) || math.IsInf(f, 0) {
			return 0, fmt.Errorf("parse time")
		}
		return f, nil
	case "unix_millis":
		f, err := strconv.ParseFloat(v, 64)
		if err != nil || math.IsNaN(f) || math.IsInf(f, 0) {
			return 0, fmt.Errorf("parse time")
		}
		return f, nil
	case "rfc3339":
		t, err := time.Parse(time.RFC3339Nano, v)
		if err != nil {
			return 0, err
		}
		return float64(t.UnixNano()) / 1e9, nil
	default:
		return 0, fmt.Errorf("parse time")
	}
}

func (s *WindowStage) renderTime(t float64) string {
	switch s.cfg.emitTimeFormat {
	case "unix_seconds":
		if t == math.Trunc(t) {
			return strconv.FormatFloat(t, 'f', 0, 64)
		}
		return strconv.FormatFloat(t, 'g', -1, 64)
	case "unix_millis":
		ms := math.Floor(t)
		if ms == math.Trunc(ms) {
			return strconv.FormatFloat(ms, 'f', 0, 64)
		}
		return strconv.FormatFloat(ms, 'g', -1, 64)
	case "rfc3339":
		ns := int64(t * 1e9)
		return time.Unix(0, ns).UTC().Format(time.RFC3339Nano)
	default:
		return strconv.FormatFloat(t, 'f', 0, 64)
	}
}

func (s *WindowStage) windowsFor(t float64) []windowRange {
	switch s.cfg.windowType {
	case "tumble":
		size := s.cfg.tumbleSize
		origin := s.cfg.tumbleOrigin
		k := math.Floor((t - origin) / size)
		start := origin + k*size
		return []windowRange{{start: start, end: start + size}}
	case "slide":
		size := s.cfg.slideSize
		step := s.cfg.slideStep
		origin := s.cfg.slideOrigin
		var out []windowRange
		// s <= t < s+size, s = origin + k*step, s >= origin
		if t < origin {
			return out
		}
		k := math.Floor((t - origin) / step)
		if k < 0 {
			k = 0
		}
		// go backwards to cover windows whose start <= t
		for kk := k; ; kk-- {
			start := origin + kk*step
			if start < origin || start+size <= t {
				break
			}
			if start <= t && t < start+size {
				out = append(out, windowRange{start: start, end: start + size})
			}
		}
		sort.Slice(out, func(i, j int) bool { return out[i].start < out[j].start })
		return out
	case "session":
		// Session is handled by returning a point window; actual merging is simplified below.
		return []windowRange{{start: t, end: t}}
	}
	return nil
}

func (s *WindowStage) applyAggregate(st *struct {
	count   int
	sum     float64
	numVals []float64
	strVals []string
	distinct map[string]struct{}
	first   string
	last    string
	hasFirst bool
}, agg windowAggConfig, r *record.Record, rNum int) error {
	switch agg.op {
	case "count":
		return nil
	case "sum", "avg", "min", "max", "p50", "p95", "stddev":
		v, ok := r.Get(agg.column)
		if !ok || v == "" {
			return nil
		}
		f, err := parseFloat(v)
		if err != nil {
			return fmt.Errorf("flowctl: window: non-numeric value in aggregate column %s at row %d", agg.column, rNum)
		}
		st.numVals = append(st.numVals, f)
		if agg.op == "sum" {
			st.sum += f
		}
	case "first", "last", "distinct":
		v, ok := r.Get(agg.column)
		if !ok || v == "" {
			return nil
		}
		if agg.op == "first" && !st.hasFirst {
			st.first = v
			st.hasFirst = true
		}
		if agg.op == "last" {
			st.last = v
		}
		if agg.op == "distinct" {
			st.distinct[v] = struct{}{}
		}
	}
	return nil
}

func (s *WindowStage) renderAggregates(st *struct {
	count   int
	sum     float64
	numVals []float64
	strVals []string
	distinct map[string]struct{}
	first   string
	last    string
	hasFirst bool
}) []string {
	vals := make([]string, len(s.cfg.aggregates))
	for i, agg := range s.cfg.aggregates {
		switch agg.op {
		case "count":
			vals[i] = strconv.Itoa(st.count)
		case "sum":
			vals[i] = formatFloat(st.sum)
		case "avg":
			if len(st.numVals) == 0 {
				vals[i] = ""
			} else {
				vals[i] = formatFloat(st.sum / float64(len(st.numVals)))
			}
		case "min":
			if len(st.numVals) == 0 {
				vals[i] = ""
			} else {
				m := st.numVals[0]
				for _, v := range st.numVals[1:] {
					if v < m {
						m = v
					}
				}
				vals[i] = formatFloat(m)
			}
		case "max":
			if len(st.numVals) == 0 {
				vals[i] = ""
			} else {
				m := st.numVals[0]
				for _, v := range st.numVals[1:] {
					if v > m {
						m = v
					}
				}
				vals[i] = formatFloat(m)
			}
		case "first":
			vals[i] = st.first
		case "last":
			vals[i] = st.last
		case "p50":
			vals[i] = percentile(st.numVals, 0.5)
		case "p95":
			vals[i] = percentile(st.numVals, 0.95)
		case "stddev":
			if len(st.numVals) <= 1 {
				vals[i] = ""
			} else {
				mean := 0.0
				for _, v := range st.numVals {
					mean += v
				}
				mean /= float64(len(st.numVals))
				varSum := 0.0
				for _, v := range st.numVals {
					d := v - mean
					varSum += d * d
				}
				vals[i] = strconv.FormatFloat(math.Sqrt(varSum/float64(len(st.numVals)-1)), 'g', 6, 64)
			}
		case "distinct":
			vals[i] = strconv.Itoa(len(st.distinct))
		}
	}
	return vals
}

func percentile(vals []float64, p float64) string {
	if len(vals) == 0 {
		return ""
	}
	sorted := make([]float64, len(vals))
	copy(sorted, vals)
	sort.Float64s(sorted)
	if len(sorted) == 1 {
		return formatFloat(sorted[0])
	}
	idx := float64(len(sorted)-1) * p
	lo := math.Floor(idx)
	hi := math.Ceil(idx)
	frac := idx - lo
	res := sorted[int(lo)] + frac*(sorted[int(hi)]-sorted[int(lo)])
	return formatFloat(res)
}

func (c windowConfig) allowedLateness() float64 {
	return 0
}

func (s *WindowStage) aggregateOutputs() int {
	return len(s.cfg.aggregates)
}

func buildWindow(idx int, sm map[string]interface{}) (Stage, error) {
	cfg := windowConfig{}

	tc, ok := getString(sm, "time_column")
	if !ok || tc == "" {
		return nil, fmt.Errorf("config: window: time_column must be a non-empty string")
	}
	cfg.timeColumn = tc

	tf, ok := getString(sm, "time_format")
	if !ok || tf == "" {
		return nil, fmt.Errorf("config: window: time_format must be unix_seconds, unix_millis, or rfc3339")
	}
	if tf != "unix_seconds" && tf != "unix_millis" && tf != "rfc3339" {
		return nil, fmt.Errorf("config: window: time_format must be unix_seconds, unix_millis, or rfc3339")
	}
	cfg.timeFormat = tf
	cfg.emitTimeFormat = tf
	if etf, ok := getString(sm, "emit_time_format"); ok {
		if etf != "unix_seconds" && etf != "unix_millis" && etf != "rfc3339" {
			return nil, fmt.Errorf("config: window: emit_time_format must be unix_seconds, unix_millis, or rfc3339")
		}
		cfg.emitTimeFormat = etf
	}

	// window type
	windowRaw, ok := sm["window"]
	if !ok {
		return nil, fmt.Errorf("config: window: exactly one of window.tumble, window.slide, or window.session is required")
	}
	windowMap, ok := windowRaw.(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("config: window: exactly one of window.tumble, window.slide, or window.session is required")
	}
	hasTumble, hasSlide, hasSession := windowMap["tumble"] != nil, windowMap["slide"] != nil, windowMap["session"] != nil
	cnt := 0
	if hasTumble {
		cnt++
	}
	if hasSlide {
		cnt++
	}
	if hasSession {
		cnt++
	}
	if cnt != 1 {
		return nil, fmt.Errorf("config: window: exactly one of window.tumble, window.slide, or window.session is required")
	}

	if hasTumble {
		cfg.windowType = "tumble"
		tm, ok := windowMap["tumble"].(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("config: window: tumble must be a mapping")
		}
		sz, err := getWindowNumber(tm, "size")
		if err != nil {
			return nil, fmt.Errorf("config: window: tumble.size must be a positive finite number")
		}
		if sz <= 0 || math.IsNaN(sz) || math.IsInf(sz, 0) {
			return nil, fmt.Errorf("config: window: tumble.size must be a positive finite number")
		}
		cfg.tumbleSize = sz
		cfg.tumbleOrigin = 0
		if origin, ok := tm["origin"]; ok {
			o, err := parseWindowNumber(origin)
			if err != nil || math.IsNaN(o) || math.IsInf(o, 0) {
				return nil, fmt.Errorf("config: window: tumble.origin must be a finite number")
			}
			cfg.tumbleOrigin = o
		}
	}
	if hasSlide {
		cfg.windowType = "slide"
		tm, ok := windowMap["slide"].(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("config: window: slide must be a mapping")
		}
		sz, err := getWindowNumber(tm, "size")
		if err != nil {
			return nil, fmt.Errorf("config: window: slide.size must be a positive finite number")
		}
		if sz <= 0 || math.IsNaN(sz) || math.IsInf(sz, 0) {
			return nil, fmt.Errorf("config: window: slide.size must be a positive finite number")
		}
		cfg.slideSize = sz
		step, err := getWindowNumber(tm, "step")
		if err != nil {
			return nil, fmt.Errorf("config: window: slide.step must be a positive finite number")
		}
		if step <= 0 || math.IsNaN(step) || math.IsInf(step, 0) {
			return nil, fmt.Errorf("config: window: slide.step must be a positive finite number")
		}
		if step > sz {
			return nil, fmt.Errorf("config: window: slide.step must be <= slide.size")
		}
		cfg.slideStep = step
		cfg.slideOrigin = 0
		if origin, ok := tm["origin"]; ok {
			o, err := parseWindowNumber(origin)
			if err != nil || math.IsNaN(o) || math.IsInf(o, 0) {
				return nil, fmt.Errorf("config: window: slide.origin must be a finite number")
			}
			cfg.slideOrigin = o
		}
	}
	if hasSession {
		cfg.windowType = "session"
		tm, ok := windowMap["session"].(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("config: window: session must be a mapping")
		}
		gap, err := getWindowNumber(tm, "gap")
		if err != nil {
			return nil, fmt.Errorf("config: window: session.gap must be a positive finite number")
		}
		if gap <= 0 || math.IsNaN(gap) || math.IsInf(gap, 0) {
			return nil, fmt.Errorf("config: window: session.gap must be a positive finite number")
		}
		cfg.sessionGap = gap
		cfg.sessionHasMax = false
		if md, ok := tm["max_duration"]; ok {
			m, err := parseWindowNumber(md)
			if err != nil || m <= 0 || math.IsNaN(m) || math.IsInf(m, 0) {
				return nil, fmt.Errorf("config: window: session.max_duration must be a positive finite number")
			}
			if m < gap {
				return nil, fmt.Errorf("config: window: session.max_duration must be >= session.gap")
			}
			cfg.sessionMaxDur = m
			cfg.sessionHasMax = true
		}
	}

	cfg.partitionBy = []string{}
	if raw, ok := sm["partition_by"]; ok {
		plist, err := toStringList(raw)
		if err != nil {
			return nil, fmt.Errorf("config: window: partition_by %v", err)
		}
		seen := map[string]bool{}
		for _, col := range plist {
			if seen[col] {
				return nil, fmt.Errorf("config: window: partition_by has duplicate column %s", col)
			}
			seen[col] = true
		}
		cfg.partitionBy = plist
	}

	agesRaw, ok := sm["aggregates"]
	if !ok {
		return nil, fmt.Errorf("config: window: aggregates must be a non-empty list")
	}
	agesList, ok := agesRaw.([]interface{})
	if !ok || len(agesList) == 0 {
		return nil, fmt.Errorf("config: window: aggregates must be a non-empty list")
	}
	seenInto := map[string]bool{}
	for i, item := range agesList {
		am, ok := item.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("config: window: aggregates[%d] must be a mapping", i)
		}
		op, ok := getString(am, "op")
		if !ok || op == "" {
			return nil, fmt.Errorf("config: window: aggregates[%d].op must be one of sum, count, avg, min, max, first, last, p50, p95, stddev, distinct", i)
		}
		validOps := map[string]bool{"sum": true, "count": true, "avg": true, "min": true, "max": true, "first": true, "last": true, "p50": true, "p95": true, "stddev": true, "distinct": true}
		if !validOps[op] {
			return nil, fmt.Errorf("config: window: aggregates[%d].op must be one of sum, count, avg, min, max, first, last, p50, p95, stddev, distinct", i)
		}
		col, hasCol := getString(am, "column")
		if op == "count" {
			if hasCol && col != "" {
				return nil, fmt.Errorf("config: window: aggregates[%d] count does not accept column", i)
			}
		} else {
			if !hasCol || col == "" {
				return nil, fmt.Errorf("config: window: aggregates[%d] op %s requires column", i, op)
			}
		}
		into, ok := getString(am, "into")
		if !ok || into == "" {
			return nil, fmt.Errorf("config: window: aggregates[%d].into must be a non-empty string", i)
		}
		if seenInto[into] {
			return nil, fmt.Errorf("config: window: aggregates has duplicate into %s", into)
		}
		if into == cfg.windowStartInto || into == cfg.windowEndInto {
			return nil, fmt.Errorf("config: window: aggregates[%d].into %s collides with window column", i, into)
		}
		for _, col := range cfg.partitionBy {
			if into == col {
				return nil, fmt.Errorf("config: window: aggregates[%d].into %s collides with partition_by column %s", i, into, col)
			}
		}
		seenInto[into] = true
		cfg.aggregates = append(cfg.aggregates, windowAggConfig{op: op, column: col, into: into})
	}

	wsi, ok := getString(sm, "window_start_into")
	if !ok || wsi == "" {
		return nil, fmt.Errorf("config: window: window_start_into must be a non-empty string")
	}
	wei, ok := getString(sm, "window_end_into")
	if !ok || wei == "" {
		return nil, fmt.Errorf("config: window: window_end_into must be a non-empty string")
	}
	if wsi == wei {
		return nil, fmt.Errorf("config: window: window_start_into collides with window_end_into")
	}
	for _, into := range seenInto {
		_ = into
	}
	for _, into := range aggregateIntos(cfg.aggregates) {
		if into == wsi {
			return nil, fmt.Errorf("config: window: window_start_into collides with aggregate into %s", into)
		}
		if into == wei {
			return nil, fmt.Errorf("config: window: window_end_into collides with aggregate into %s", into)
		}
	}
	for _, col := range cfg.partitionBy {
		if wsi == col {
			return nil, fmt.Errorf("config: window: window_start_into collides with partition_by column %s", col)
		}
		if wei == col {
			return nil, fmt.Errorf("config: window: window_end_into collides with partition_by column %s", col)
		}
	}
	cfg.windowStartInto = wsi
	cfg.windowEndInto = wei

	if raw, ok := sm["allowed_lateness"]; ok {
		al, err := parseWindowNumber(raw)
		if err != nil || al < 0 || math.IsNaN(al) || math.IsInf(al, 0) {
			return nil, fmt.Errorf("config: window: allowed_lateness must be a non-negative finite number")
		}
		cfg.allowedLatenessVal = al
	}

	cfg.onLate = "drop"
	if v, ok := getString(sm, "on_late"); ok {
		if v != "drop" && v != "include" && v != "error" {
			return nil, fmt.Errorf("config: window: on_late must be drop, include, or error")
		}
		cfg.onLate = v
	}
	cfg.onMissingTime = "error"
	if v, ok := getString(sm, "on_missing_time"); ok {
		if v != "drop" && v != "error" {
			return nil, fmt.Errorf("config: window: on_missing_time must be drop or error")
		}
		cfg.onMissingTime = v
	}
	cfg.onNonParseable = "error"
	if v, ok := getString(sm, "on_non_parseable_time"); ok {
		if v != "drop" && v != "error" {
			return nil, fmt.Errorf("config: window: on_non_parseable_time must be drop or error")
		}
		cfg.onNonParseable = v
	}

	cfg.emitEmptyWindows = false
	if v, ok, err := getBool(sm, "emit_empty_windows"); ok {
		if err != nil {
			return nil, fmt.Errorf("config: window: emit_empty_windows must be a boolean")
		}
		cfg.emitEmptyWindows = v
	}

	cfg.emitSchema = "wide"
	if v, ok := getString(sm, "emit_schema"); ok {
		if v != "wide" && v != "long" {
			return nil, fmt.Errorf("config: window: emit_schema must be wide or long")
		}
		cfg.emitSchema = v
	}
	cfg.metricNameInto = ""
	cfg.metricValueInto = ""
	if cfg.emitSchema == "long" {
		mn, ok1 := getString(sm, "metric_name_into")
		mv, ok2 := getString(sm, "metric_value_into")
		if !ok1 || mn == "" || !ok2 || mv == "" {
			return nil, fmt.Errorf("config: window: emit_schema long requires metric_name_into and metric_value_into")
		}
		if mn == mv {
			return nil, fmt.Errorf("config: window: metric_name_into collides with metric_value_into")
		}
		for _, col := range colsForLongCollision(cfg) {
			if mn == col {
				return nil, fmt.Errorf("config: window: metric_name_into collides with %s", col)
			}
			if mv == col {
				return nil, fmt.Errorf("config: window: metric_value_into collides with %s", col)
			}
		}
		cfg.metricNameInto = mn
		cfg.metricValueInto = mv
	} else {
		if _, ok := sm["metric_name_into"]; ok {
			return nil, fmt.Errorf("config: window: metric_name_into/value_into are only valid when emit_schema is long")
		}
		if _, ok := sm["metric_value_into"]; ok {
			return nil, fmt.Errorf("config: window: metric_name_into/value_into are only valid when emit_schema is long")
		}
	}

	cfg.emitMode = "batched_at_end"
	if v, ok := getString(sm, "emit_mode"); ok {
		if v != "batched_at_end" && v != "closed_on_advance" {
			return nil, fmt.Errorf("config: window: emit_mode must be batched_at_end or closed_on_advance")
		}
		cfg.emitMode = v
	}
	if cfg.emitMode == "closed_on_advance" && cfg.windowType == "session" {
		return nil, fmt.Errorf("config: window: emit_mode closed_on_advance is not compatible with session windows")
	}

	cfg.outOrder = "metric-first"
	if v, ok := getString(sm, "out_order"); ok {
		if cfg.emitSchema != "long" {
			return nil, fmt.Errorf("config: window: out_order is only valid when emit_schema is long")
		}
		if v != "metric-first" && v != "aggregate-first" {
			return nil, fmt.Errorf("config: window: out_order must be metric-first or aggregate-first")
		}
		cfg.outOrder = v
	}

	return &WindowStage{cfg: cfg}, nil
}

func aggregateIntos(aggregates []windowAggConfig) []string {
	out := make([]string, len(aggregates))
	for i, a := range aggregates {
		out[i] = a.into
	}
	return out
}

func colsForLongCollision(cfg windowConfig) []string {
	cols := append([]string{}, cfg.partitionBy...)
	cols = append(cols, cfg.windowStartInto, cfg.windowEndInto)
	cols = append(cols, aggregateIntos(cfg.aggregates)...)
	return cols
}

func getWindowNumber(m map[string]interface{}, key string) (float64, error) {
	v, ok := m[key]
	if !ok {
		return 0, fmt.Errorf("missing")
	}
	return parseWindowNumber(v)
}

func parseWindowNumber(v interface{}) (float64, error) {
	switch n := v.(type) {
	case int:
		return float64(n), nil
	case int64:
		return float64(n), nil
	case float64:
		return n, nil
	case string:
		return strconv.ParseFloat(n, 64)
	default:
		return 0, fmt.Errorf("not a number")
	}
}
